def sha(body):
    return hashlib.sha256(body).hexdigest()


def regular(path):
    assert path.is_file() and not path.is_symlink(), str(path)
    return path.read_bytes()


def main():
    assert os.geteuid() == 1001, "capture must run as the existing runner user"
    started = datetime.datetime.now(datetime.timezone.utc).isoformat()
    source = Path(REQUEST['source_root'])
    manifest_path = Path(REQUEST['parent_manifest_path'])
    before_manifest = regular(manifest_path)
    assert sha(before_manifest) == REQUEST['parent_manifest_sha256'], "current parent manifest differs"
    manifest = dict((n, h) for h, n in [line.split('  ', 1) for line in before_manifest.decode().splitlines()])
    assert len(manifest) == REQUEST['parent_manifest_count'] == 167
    names = [row['path'] for row in REQUEST['files']]
    assert len(names) == len(set(names)) == 30
    assert all(not PurePosixPath(n).is_absolute() and '..' not in PurePosixPath(n).parts for n in names)
    assert not (set(names) & set(manifest)), "requested subset unexpectedly overlaps the parent manifest"
    captured = {}
    before = {}
    for name in names:
        path = source / name
        assert path.resolve().is_relative_to(source.resolve()), name
        body = regular(path)
        captured['source/' + name] = body
        before[name] = {'sha256': sha(body), 'bytes': len(body)}
    after = {}
    for name in names:
        body = regular(source / name)
        after[name] = {'sha256': sha(body), 'bytes': len(body)}
    assert after == before, "selected source bytes changed during capture"
    after_manifest = regular(manifest_path)
    assert after_manifest == before_manifest, "parent manifest changed during capture"
    captured['parent-source-sha256.txt'] = before_manifest
    result = {
        'schema': 1,
        'status': 'READ_ONLY_CAPTURE_VERIFIED',
        'scope': 'Only the30 source bodies absent from the proposed245 manifest; no guest writes, subprocesses, service/UI/device actions or target acceptance.',
        'source_root': str(source), 'parent_manifest_path': str(manifest_path),
        'parent_manifest_sha256_before': sha(before_manifest),
        'parent_manifest_sha256_after': sha(after_manifest), 'parent_manifest_count': len(manifest),
        'plan_sha256': REQUEST['plan_sha256'], 'candidate245_manifest_sha256': REQUEST['candidate245_manifest_sha256'],
        'started': started, 'finished': datetime.datetime.now(datetime.timezone.utc).isoformat(),
        'files': [dict(row, current_before=before[row['path']], current_after=after[row['path']],
                       comparison_to_plan='same' if before[row['path']]['sha256'] == row['sha256'] else 'different')
                  for row in REQUEST['files']],
        'archive_members': {name: {'sha256': sha(body), 'bytes': len(body)} for name, body in captured.items()},
        'boundary': 'Manifest identity is context; these30 bodies are outside that partial manifest. Remaining167 source bodies are not rehashed by this light capture.'}
    captured['capture-result.json'] = (json.dumps(result, indent=2) + '\n').encode()
    with tarfile.open(fileobj=sys.stdout.buffer, mode='w|gz', compresslevel=1) as archive:
        for name, body in sorted(captured.items()):
            member = tarfile.TarInfo(name); member.size = len(body); member.mode = 0o644
            archive.addfile(member, io.BytesIO(body))


if __name__ == '__main__':
    main()
